import java.io.BufferedReader
import java.io.BufferedWriter
import java.io.InputStreamReader
import java.io.OutputStreamWriter
import java.io.Reader
import java.io.Writer
import java.util.ArrayDeque
import java.util.Locale

// (づ°ω°)づﾐe★゜・。。・゜゜・。。・゜☆゜・。。・゜゜・。。・゜
class Solution {
    fun solve() {
        val n = readInt()
        val m = readInt()

        if (m == 1)
            write(n - 1)
        else
            write(1L * n * (m - 1))
    }

    companion object {
        // region Main

        lateinit var reader: BufferedReader
        lateinit var writer: Writer

        @JvmStatic
        fun main(args: Array<String>) {
            reader = BufferedReader(InputStreamReader(System.`in`))
            writer = BufferedWriter(OutputStreamWriter(System.out))

            Solution().solve()

            reader.close()
            writer.close()
        }

        // endregion

        // region Read / Write
        private var currentLineTokens = ArrayDeque<String>()

        private fun readAndSplitLine(): Array<String> =
            reader.readLine().split(' ', '\t').filter { it.isNotEmpty() }.toTypedArray()

        fun readToken(): String {
            while (currentLineTokens.isEmpty()) currentLineTokens = ArrayDeque(readAndSplitLine().toList())
            return currentLineTokens.poll()
        }

        fun readInt(): Int = readToken().toInt()
        fun readLong(): Long = readToken().toLong()
        fun readDouble(): Double = readToken().toDouble()
        fun readIntArray(): IntArray = readAndSplitLine().map { it.toInt() }.toIntArray()
        fun readLongArray(): LongArray = readAndSplitLine().map { it.toLong() }.toLongArray()
        fun readDoubleArray(): DoubleArray = readAndSplitLine().map { it.toDouble() }.toDoubleArray()

        fun readIntMatrix(numberOfRows: Int): Array<IntArray> {
            val matrix = Array(numberOfRows) { IntArray(0) }
            for (i in 0 until numberOfRows) matrix[i] = readIntArray()
            return matrix
        }

        fun readAndTransposeIntMatrix(numberOfRows: Int): Array<IntArray> {
            val matrix = readIntMatrix(numberOfRows)
            val ret = Array(matrix[0].size) { IntArray(numberOfRows) }
            for (i in ret.indices) {
                for (j in 0 until numberOfRows) ret[i][j] = matrix[j][i]
            }
            return ret
        }

        fun readLines(quantity: Int): Array<String> {
            val lines = Array(quantity) { "" }
            for (i in 0 until quantity) lines[i] = reader.readLine().trim()
            return lines
        }

        fun <T> writeArray(array: Iterable<T>) {
            writer.write(array.joinToString(" "))
            writer.write("\n")
        }

        fun write(vararg array: Any?) = writeArray(array.toList())

        fun <T> writeLines(array: Iterable<T>) {
            for (a in array) {
                writer.write(a.toString())
                writer.write("\n")
            }
        }

        private class SDictionary<TKey, TValue> : HashMap<TKey, TValue>()

        private inline fun <reified T> init(size: Int, factory: () -> T): Array<T> = Array(size) { factory() }
        // endregion
    }
}
